// PlayerJump.cs — ground check con Raycast + contador de saltos
using UnityEngine;

[RequireComponent(typeof(Rigidbody2D))]
public class PlayerJump : MonoBehaviour
{
    [SerializeField] private float jumpForce   = 8f;
    [SerializeField] private int  maxJumps     = 2;      // 1 = solo suelo, 2 = double jump
    [SerializeField] private LayerMask groundLayer;
    [SerializeField] private Transform groundCheck;      // Transform vacío en los pies del personaje
    [SerializeField] private float checkRadius = 0.1f;

    private Rigidbody2D _rb;
    private int _jumpsLeft;

    private void Awake()
    {
        _rb = GetComponent<Rigidbody2D>();
        _jumpsLeft = maxJumps;
    }

    private void Update()
    {
        // Ground check puntual cada frame — sin delay, sin jitter
        bool isGrounded = Physics2D.OverlapCircle(
            groundCheck.position, checkRadius, groundLayer);

        if (isGrounded)
            _jumpsLeft = maxJumps; // resetear al tocar suelo

        if (Input.GetButtonDown("Jump") && _jumpsLeft > 0)
        {
            // Resetea la velocidad vertical antes del impulso para saltos consistentes
            _rb.linearVelocity = new Vector2(_rb.linearVelocity.x, 0f);
            _rb.AddForce(Vector2.up * jumpForce, ForceMode2D.Impulse);
            _jumpsLeft--;
        }
    }
}

