// Projectile.cs — velocidad inicial calculada con cinemática de tiro parabólico
using UnityEngine;

[RequireComponent(typeof(Rigidbody2D))]
public class Projectile : MonoBehaviour
{
    // Ángulo de lanzamiento configurable desde el Inspector (en grados)
    [SerializeField] private float launchAngle = 45f;

    private Rigidbody2D _rb;

    private void Awake() => _rb = GetComponent<Rigidbody2D>();

    // Fórmula: dado ángulo θ y distancia horizontal d,
    // v₀ = sqrt(d * g / sin(2θ))
    // Derivado de: d = v₀² * sin(2θ) / g
    public void Launch(Vector3 targetPosition)
    {
        float g     = Mathf.Abs(Physics2D.gravity.y);
        float dx    = targetPosition.x - transform.position.x;
        float dy    = targetPosition.y - transform.position.y;
        float theta = launchAngle * Mathf.Deg2Rad;

        // Velocidad inicial para alcanzar (dx, dy) con ángulo theta
        // Basado en ecuaciones de movimiento uniforme + caída libre
        float vx = dx / (Mathf.Sqrt(2f * (dx * Mathf.Tan(theta) - dy) / g));
        float vy = vx * Mathf.Tan(theta);

        // Preserva la dirección correcta en X
        if (dx < 0f) vx = -Mathf.Abs(vx);

        _rb.linearVelocity = new Vector2(vx, vy);
    }
}

