// CameraFollow.cs — seguimiento suave con SmoothDamp + dead zone + clamp de mundo
using UnityEngine;

public class CameraFollow : MonoBehaviour
{
    [SerializeField] private Transform target;
    [SerializeField] private float smoothTime  = 0.2f;  // tiempo de suavizado
    [SerializeField] private Vector2 offset    = Vector2.zero;
    [SerializeField] private Vector2 deadZone  = new Vector2(0.5f, 0.3f);

    [Header("Límites del mundo")]
    [SerializeField] private float minX = -50f;
    [SerializeField] private float maxX =  50f;
    [SerializeField] private float minY = -20f;
    [SerializeField] private float maxY =  20f;

    private Vector3 _velocity = Vector3.zero;

    private void LateUpdate()
    {
        if (target == null) return;

        Vector3 desired = new Vector3(
            target.position.x + offset.x,
            target.position.y + offset.y,
            -10f
        );

        // Dead zone: solo moverse si el target sale del área central
        Vector3 delta = desired - transform.position;
        if (Mathf.Abs(delta.x) < deadZone.x) desired.x = transform.position.x;
        if (Mathf.Abs(delta.y) < deadZone.y) desired.y = transform.position.y;

        // Suavizado con inercia — elimina el movimiento brusco
        Vector3 smoothed = Vector3.SmoothDamp(
            transform.position, desired, ref _velocity, smoothTime);

        // Clamp de límites de mundo
        smoothed.x = Mathf.Clamp(smoothed.x, minX, maxX);
        smoothed.y = Mathf.Clamp(smoothed.y, minY, maxY);

        transform.position = smoothed;
    }
}

