// === ALTERNATIVA A: Rigidbody kinematic con MovePosition ===
using UnityEngine;

[RequireComponent(typeof(Rigidbody))]
public class EnemyMovement : MonoBehaviour
{
    [SerializeField] private float speed = 3f;
    [SerializeField] private Transform player;

    private Rigidbody _rb;

    private void Awake()
    {
        _rb = GetComponent<Rigidbody>();
        _rb.isKinematic = true; // kinematic: Unity respeta colisiones pero no aplica física
    }

    // FixedUpdate garantiza que el movimiento va sincronizado con el solver de físicas
    private void FixedUpdate()
    {
        if (player == null) return;

        Vector3 direction = (player.position - transform.position).normalized;
        Vector3 newPos    = _rb.position + direction * speed * Time.fixedDeltaTime;
        // MovePosition respeta colisiones: el Rigidbody no atraviesa colisionadores
        _rb.MovePosition(newPos);
    }
}

