// WaypointPatrol.cs
using System.Collections.Generic;
using UnityEngine;

public class WaypointPatrol : MonoBehaviour
{
    [SerializeField] private List<Transform> _waypoints;
    [SerializeField] private float speed = 2f;
    [SerializeField] private float reachThreshold = 0.3f;

    // Problema: O(n) cada frame por enemigo → O(n × enemigos) en total
    // Con 15 enemigos y 40 waypoints: 600 cálculos de distancia por frame
    private void Update()
    {
        if (_waypoints == null || _waypoints.Count == 0) return;

        // Buscar el waypoint más cercano — innecesario si se usa índice secuencial
        Transform nearest = null;
        float minDist     = float.MaxValue;

        foreach (Transform wp in _waypoints)
        {
            float d = Vector3.Distance(transform.position, wp.position);
            if (d < minDist) { minDist = d; nearest = wp; }
        }

        // Moverse hacia el waypoint más cercano con Translate (no respeta colisiones)
        if (nearest != null)
        {
            Vector3 dir = (nearest.position - transform.position).normalized;
            transform.Translate(dir * speed * Time.deltaTime);
        }
    }
}

