// WaypointPatrol.cs — patrulla secuencial con NavMeshAgent, sin búsqueda O(n) por frame
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.AI;

[RequireComponent(typeof(NavMeshAgent))]
public class WaypointPatrol : MonoBehaviour
{
    [SerializeField] private List<Transform> _waypoints;

    private NavMeshAgent _agent;
    private int _waypointIndex;

    private void Awake()
    {
        _agent = GetComponent<NavMeshAgent>();
        _waypointIndex = 0;
    }

    private void Start()
    {
        if (_waypoints != null && _waypoints.Count > 0)
            GoToNext();
    }

    // Update ahora es O(1): solo comprueba si llegó al destino actual
    private void Update()
    {
        if (_waypoints == null || _waypoints.Count == 0) return;

        // HasPath y remainingDistance son O(1) — sin iteración
        if (!_agent.pathPending && _agent.remainingDistance < 0.3f)
            GoToNext();
    }

    private void GoToNext()
    {
        // Índice secuencial — costo O(1), sin búsqueda por distancia
        _agent.SetDestination(_waypoints[_waypointIndex].position);
        _waypointIndex = (_waypointIndex + 1) % _waypoints.Count;
    }
}

