// CharacterDeath.cs — ragdoll controlado: solo hueso raíz + impulso dirigido
using UnityEngine;

public class CharacterDeath : MonoBehaviour
{
    [SerializeField] private Rigidbody _rootRb;        // Asignar el hueso raíz (Hips) en el Inspector
    [SerializeField] private float impulseMagnitude = 6f;
    [SerializeField] private float upwardBias       = 2f; // componente vertical del impulso

    private Animator _animator;

    private void Awake()
    {
        _animator = GetComponent<Animator>();

        // Los huesos hijos ya tienen Rigidbody + ConfigurableJoint configurados en prefab
        // Empezamos con todos kinematic — el Animator los controla
        SetKinematic(true);
    }

    public void Die(Vector3 hitDirection)
    {
        _animator.enabled = false; // desactivar antes de liberar física

        // Solo el Rigidbody raíz se activa: los hijos lo siguen por joints
        SetKinematic(false);

        // Impulso dirigido desde la dirección del golpe — no aleatorio
        Vector3 impulse = hitDirection.normalized * impulseMagnitude
                        + Vector3.up * upwardBias;
        _rootRb.AddForce(impulse, ForceMode.Impulse);
    }

    // Utilidad para activar/desactivar todos los Rigidbodies (llamada solo en Awake y Die)
    private void SetKinematic(bool value)
    {
        foreach (Rigidbody rb in GetComponentsInChildren<Rigidbody>())
            rb.isKinematic = value;
    }
}

