using UnityEngine;

public class Bullet : MonoBehaviour
{
    [SerializeField] private float damage = 25f;

    // Problema 1: sin layer check — colisiona con decoración, suelo, jugador
    // Problema 2: TryGetComponent en CUALQUIER cosa que toque (costo innecesario)
    // Problema 3: sin Layer Collision Matrix el broadphase genera todos los pares
    private void OnTriggerEnter(Collider other)
    {
        if (other.TryGetComponent<IDamageable>(out var target))
        {
            target.TakeDamage(damage);
        }

        // El proyectil se destruye al tocar cualquier cosa, incluso decoración
        Destroy(gameObject);
    }
}

