// Bullet.cs — layer check + pool, configurado con Layer Collision Matrix
// PASO 1 (en Unity Editor):
//   Edit > Project Settings > Physics > Layer Collision Matrix
//   Crea layer "Projectile" y layer "Enemy"
//   Desmarca TODAS las interacciones de "Projectile" excepto con "Enemy"
//   → El broadphase descarta todos los demás pares en fase temprana
//
// PASO 2: asigna el layer "Projectile" al GameObject de la bala

using UnityEngine;

public class Bullet : MonoBehaviour
{
    [SerializeField] private float damage = 25f;
    // Solo el layer "Enemy" debe estar en esta mask
    [SerializeField] private LayerMask _targetLayer;

    // Referencia al pool para devolver en lugar de Destroy
    private BulletPool _pool;

    public void Init(BulletPool pool)
    {
        _pool = pool;
    }

    // Gracias a la Layer Collision Matrix, Unity NUNCA llama este método
    // si el otro objeto no está en el layer "Enemy" — costo cero en broadphase
    private void OnTriggerEnter(Collider other)
    {
        // Doble check en código: garantía extra si la matrix no está configurada
        if ((_targetLayer.value & (1 << other.gameObject.layer)) == 0)
            return; // no es un target válido — ignorar sin hacer nada

        if (other.TryGetComponent<IDamageable>(out var target))
            target.TakeDamage(damage);

        // Devolver al pool en lugar de Destroy — sin GC, sin hitches
        ReturnToPool();
    }

    private void ReturnToPool()
    {
        gameObject.SetActive(false);
        _pool?.Return(this);
    }
}
